package com.localmind.dao.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="app_users",uniqueConstraints=@UniqueConstraint(columnNames="username")) public class AppUser{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=60)private String username;@Column(nullable=false)private String password;@Enumerated(EnumType.STRING)@Column(nullable=false,length=10)private Role role=Role.USER;@Column(nullable=false)private boolean enabled=true;@Column(nullable=false,updatable=false)private Instant createdAt=Instant.now();public enum Role{ADMIN,USER}public Long getId(){return id;}public String getUsername(){return username;}public void setUsername(String v){username=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}public Role getRole(){return role;}public void setRole(Role v){role=v;}public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public Instant getCreatedAt(){return createdAt;}}